1	/**
2	 * Managed first-month-free promotion — the atomic redemption core.
3	 *
4	 * This mirrors lib/order.ts `claimOrderCoupon`: a conditional INSERT guarded by
5	 * two @@unique constraints (PromoRedemption `@@unique([promoId,userId])` and
6	 * `@@unique([promoId,ipHash])`) that runs INSIDE the order's charge transaction.
7	 * If the insert violates either constraint (this account OR this IP already
8	 * redeemed) it returns `{ claimed: false }` — it never throws for that case — so
9	 * the caller can charge the FULL price and still complete the order.
10	 *
11	 * THE MONEY RULE (owner will review this file personally):
12	 *   - The free-month credit is applied to an order ONLY when `claimed === true`.
13	 *   - If the claim is lost (already redeemed by account/IP) OR the promo is
14	 *     switched off via the `first_month_free_enabled` setting, the customer is
15	 *     charged the FULL price. The order still succeeds — it just isn't free.
16	 *   - The caps are FIXED at 1/account + 1/IP and are enforced ONLY by the two
17	 *     unique constraints. There is no configurable cap to drift out of sync.
18	 *
19	 * WHY A TYPED VIEW instead of `db.promoRedemption` directly: the Prisma client in
20	 * this tree is symlinked from prod and is only regenerated at deploy time, so its
21	 * types do not yet know about the new PromoRedemption model. Rather than sprinkle
22	 * `as any` across four money-critical order flows, every raw-delegate access is
23	 * contained HERE behind `promoDelegate(...)`, and the rest of the codebase calls
24	 * the strongly-typed helpers below. When the client is regenerated the runtime is
25	 * identical; only these casts become redundant.
26	 */
27	
28	import { Prisma } from "@prisma/client";
29	import { db } from "./db";
30	
31	/** The single managed promo id. */
32	export const FIRST_MONTH_FREE_PROMO_ID = "first-month-free";
33	
34	/** Products the promo can be granted on (matches PromoRedemption.serviceType). */
35	export type PromoServiceType = "VPS" | "HOSTING" | "EMAIL" | "GAME";
36	
37	/** A minimal, honestly-typed shape of the row we read back. */
38	export type PromoRedemptionRow = {
39	  id: string;
40	  promoId: string;
41	  userId: string;
42	  ipHash: string | null;
43	  serviceType: string;
44	  campaign: string;
45	  orderRef: string | null;
46	  renewed: boolean;
47	  renewedAt: Date | null;
48	  chargedCents: number;
49	  createdAt: Date;
50	};
51	
52	/**
53	 * The subset of the PromoRedemption Prisma delegate this module uses, typed by
54	 * hand so the call sites stay type-checked even before the client is regenerated.
55	 */
56	type PromoDelegate = {
57	  create(args: {
58	    data: {
59	      promoId?: string;
60	      userId: string;
61	      ipHash: string | null;
62	      serviceType: string;
63	      campaign: string;
64	      orderRef?: string | null;
65	      chargedCents: number;
66	    };
67	    select?: { id: true };
68	  }): Promise<{ id: string }>;
69	  findUnique(args: {
70	    where: { promoId_userId: { promoId: string; userId: string } };
71	    select?: { id: true };
72	  }): Promise<{ id: string } | null>;
73	  findFirst(args: {
74	    where: { promoId: string; ipHash: string };
75	    select?: { id: true };
76	  }): Promise<{ id: string } | null>;
77	  findMany(args?: {
78	    where?: { promoId?: string; renewed?: boolean };
79	    orderBy?: { createdAt: "asc" | "desc" };
80	  }): Promise<PromoRedemptionRow[]>;
81	  updateMany(args: {
82	    where: { promoId: string; orderRef: string; renewed?: boolean };
83	    data: { renewed: boolean; renewedAt: Date };
84	  }): Promise<{ count: number }>;
85	  update(args: {
86	    where: { id: string };
87	    data: { orderRef?: string | null; chargedCents?: number };
88	  }): Promise<{ id: string }>;
89	  count(args?: { where?: { promoId?: string; renewed?: boolean } }): Promise<number>;
90	};
91	
92	/** Anything that carries a `promoRedemption` delegate — the client or a tx client. */
93	type PromoClient = Prisma.TransactionClient | typeof db;
94	
95	/** The one place the stale-client cast lives. */
96	function promoDelegate(client: PromoClient): PromoDelegate {
97	  return (client as unknown as { promoRedemption: PromoDelegate }).promoRedemption;
98	}
99	
100	/** Is the sitewide first-month-free offer switched on? (Owner toggle.) */
101	export async function firstMonthFreeEnabled(): Promise<boolean> {
102	  // Imported lazily so this module stays importable from the worker (no request
103	  // scope) without dragging server-only settings wiring into every consumer.
104	  const { getSettingBool } = await import("./settings");
105	  return getSettingBool("first_month_free_enabled", true);
106	}
107	
108	/**
109	 * Which products the first-month-free promo is granted on. Owner decision
110	 * (2026-08-11): **Shared Web Hosting ONLY**. A free month of a $2.99–$8.99
111	 * hosting plan is a cheap acquisition offer for the first paid ad channel;
112	 * a free month of a $6.49–$32.99 VPS (or a game/email plan) is real exposure.
113	 * VPS / EMAIL / GAME always bill full. To extend the promo to another product
114	 * later, add its PromoServiceType here — every order flow reads this one gate,
115	 * so nothing else changes.
116	 */
117	export const FIRST_MONTH_FREE_SERVICES: PromoServiceType[] = ["HOSTING"];
118	
119	/** Does the first-month-free promo apply to this product? (See above.) */
120	export function firstMonthFreeAppliesTo(service: PromoServiceType): boolean {
121	  return FIRST_MONTH_FREE_SERVICES.includes(service);
122	}
123	
124	/**
125	 * Read-only pre-check: could THIS user / IP still claim the promo? Mirrors
126	 * `orderCouponClaimable` — used before the wallet balance gate so a first-time,
127	 * $0-balance customer can be quoted the free (zero) price and pass the gate,
128	 * while a repeat account/IP is quoted (and gated against) the full price. It is
129	 * advisory only; the authoritative decision is the atomic `claimFirstMonthFree`
130	 * inside the charge tx, which is the sole arbiter of whether money is discounted.
131	 */
132	export async function firstMonthFreeEligible(
133	  userId: string,
134	  ipHash: string | null,
135	): Promise<boolean> {
136	  const d = promoDelegate(db);
137	  const byUser = await d.findUnique({
138	    where: { promoId_userId: { promoId: FIRST_MONTH_FREE_PROMO_ID, userId } },
139	    select: { id: true },
140	  });
141	  if (byUser) return false;
142	  if (ipHash) {
143	    const byIp = await d.findFirst({
144	      where: { promoId: FIRST_MONTH_FREE_PROMO_ID, ipHash },
145	      select: { id: true },
146	    });
147	    if (byIp) return false;
148	  }
149	  return true;
150	}
151	
152	export type ClaimResult = { claimed: true; id: string } | { claimed: false };
153	
154	/**
155	 * THE ATOMIC CLAIM. Conditional INSERT of a PromoRedemption inside the caller's
156	 * charge transaction. Returns `{ claimed: true, id }` on success, or
157	 * `{ claimed: false }` when the row already exists for this account OR this IP
158	 * (Prisma P2002 on either unique constraint). Any OTHER database error is
159	 * rethrown so it rolls the whole charge tx back — a lost claim is expected and
160	 * cheap; an unexpected failure must not silently grant a free month.
161	 *
162	 * `orderRef` is usually still unknown here (the server/account id is generated
163	 * later in the same tx), so it is filled in afterwards via `setPromoOrderRef`.
164	 */
165	export async function claimFirstMonthFree(
166	  tx: Prisma.TransactionClient,
167	  opts: {
168	    userId: string;
169	    ipHash: string | null;
170	    serviceType: PromoServiceType;
171	    campaign: string;
172	    chargedCents: number;
173	    orderRef?: string | null;
174	  },
175	): Promise<ClaimResult> {
176	  try {
177	    const row = await promoDelegate(tx).create({
178	      data: {
179	        promoId: FIRST_MONTH_FREE_PROMO_ID,
180	        userId: opts.userId,
181	        ipHash: opts.ipHash,
182	        serviceType: opts.serviceType,
183	        campaign: opts.campaign,
184	        orderRef: opts.orderRef ?? null,
185	        chargedCents: opts.chargedCents,
186	      },
187	      select: { id: true },
188	    });
189	    return { claimed: true, id: row.id };
190	  } catch (e) {
191	    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002") {
192	      // Unique violation on (promo,user) or (promo,ipHash): already redeemed.
193	      return { claimed: false };
194	    }
195	    throw e;
196	  }
197	}
198	
199	/**
200	 * Backfill the created server/account/subscription id (and the final charged
201	 * amount) onto a redemption we just claimed, in the same tx. Kept off the claim
202	 * itself because the resource id is minted after the claim within the tx.
203	 */
204	export async function setPromoOrderRef(
205	  tx: Prisma.TransactionClient,
206	  redemptionId: string,
207	  orderRef: string,
208	  chargedCents: number,
209	): Promise<void> {
210	  await promoDelegate(tx).update({
211	    where: { id: redemptionId },
212	    data: { orderRef, chargedCents },
213	  });
214	}
215	
216	/**
217	 * Mark the promo redemption anchored to `orderRef` as RENEWED, the first time
218	 * that service bills its SECOND term. Idempotent: the `renewed: false` guard
219	 * means a repeated/racing renewal sweep matches zero rows and does nothing.
220	 * Called inside the renewal charge tx so it commits with the money.
221	 */
222	export async function markPromoRenewed(
223	  tx: Prisma.TransactionClient,
224	  orderRef: string,
225	): Promise<void> {
226	  await promoDelegate(tx).updateMany({
227	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, orderRef, renewed: false },
228	    data: { renewed: true, renewedAt: new Date() },
229	  });
230	}
231	
232	/** One-month credit for a flat-priced term (used by the game flow). */
233	export function firstMonthCreditCents(termPriceCents: number, termMonths: number): number {
234	  if (termMonths <= 1) return termPriceCents; // whole (single-month) term is free
235	  const oneMonth = Math.round(termPriceCents / termMonths);
236	  return Math.min(termPriceCents, oneMonth);
237	}
238	
239	// ---------------------------------------------------------------------------
240	// Campaign tag (from the /go/<slug>?c=<campaign> cookie)
241	// ---------------------------------------------------------------------------
242	
243	/** The cookie the /go link sets and the order flows read for attribution. */
244	export const PROMO_CAMPAIGN_COOKIE = "nx_promo_campaign";
245	
246	/** Keep campaign tags to a safe, bounded alnum-dash slug (≤40). */
247	export function sanitizeCampaign(raw: string | null | undefined): string {
248	  return String(raw ?? "")
249	    .replace(/[^a-zA-Z0-9-]/g, "")
250	    .slice(0, 40);
251	}
252	
253	/**
254	 * Read + sanitize the campaign tag from an already-resolved cookie jar. Takes the
255	 * jar (not `cookies()`) so this module never imports `next/headers` — that keeps
256	 * it importable from the worker, which has no request scope.
257	 */
258	export function promoCampaignFromCookie(jar: {
259	  get(name: string): { value: string } | undefined;
260	}): string {
261	  return sanitizeCampaign(jar.get(PROMO_CAMPAIGN_COOKIE)?.value);
262	}
263	
264	// ---------------------------------------------------------------------------
265	// Admin stats
266	// ---------------------------------------------------------------------------
267	
268	export type PromoCampaignStat = {
269	  campaign: string;
270	  total: number;
271	  renewed: number;
272	};
273	
274	export type PromoStats = {
275	  total: number;
276	  renewed: number;
277	  /** renewed / total, 0..1. */
278	  conversion: number;
279	  byCampaign: PromoCampaignStat[];
280	  /** Approximate recovered revenue (one renewal term at list price), in cents. */
281	  revenueRecoveredCents: number;
282	  /** True when revenueRecovered had to fall back to an approximation. */
283	  revenueApproximate: boolean;
284	};
285	
286	/**
287	 * Aggregate redemption + conversion stats for the admin Promotions page.
288	 *
289	 * Revenue recovered is APPROXIMATE: for each renewed redemption we price ONE
290	 * renewal term at the underlying plan's current list price (VPS/hosting use the
291	 * plan monthly price; email/game use their stored term price). It is a lower/near
292	 * estimate — it ignores add-ons and multi-term VPS — hence `revenueApproximate`.
293	 */
294	export async function promoStats(): Promise<PromoStats> {
295	  const rows = await promoDelegate(db).findMany({
296	    where: { promoId: FIRST_MONTH_FREE_PROMO_ID },
297	    orderBy: { createdAt: "desc" },
298	  });
299	
300	  const total = rows.length;
301	  const renewedRows = rows.filter((r) => r.renewed);
302	  const renewed = renewedRows.length;
303	
304	  const byCampaignMap = new Map<string, PromoCampaignStat>();
305	  for (const r of rows) {
306	    const key = r.campaign || "(organic)";
307	    const stat = byCampaignMap.get(key) ?? { campaign: key, total: 0, renewed: 0 };
308	    stat.total += 1;
309	    if (r.renewed) stat.renewed += 1;
310	    byCampaignMap.set(key, stat);
311	  }
312	  const byCampaign = [...byCampaignMap.values()].sort((a, b) => b.total - a.total);
313	
314	  // Approximate recovered revenue: one renewal term at list price per renewed row.
315	  let revenueRecoveredCents = 0;
316	  let revenueApproximate = false;
317	  const refs = (type: PromoServiceType) =>
318	    renewedRows.filter((r) => r.serviceType === type && r.orderRef).map((r) => r.orderRef as string);
319	
320	  const vpsRefs = refs("VPS");
321	  const gameRefs = refs("GAME");
322	  const serverRefs = [...vpsRefs, ...gameRefs];
323	  if (serverRefs.length) {
324	    const servers = await db.server.findMany({
325	      where: { id: { in: serverRefs } },
326	      select: { id: true, plan: { select: { priceCents: true } }, gamePlan: { select: { priceCents: true } } },
327	    });
328	    for (const s of servers) {
329	      revenueRecoveredCents += s.gamePlan?.priceCents ?? s.plan?.priceCents ?? 0;
330	    }
331	    revenueApproximate = true;
332	  }
333	
334	  const hostRefs = refs("HOSTING");
335	  if (hostRefs.length) {
336	    const accounts = await db.hostingAccount.findMany({
337	      where: { id: { in: hostRefs } },
338	      select: { plan: { select: { priceCents: true } } },
339	    });
340	    for (const a of accounts) revenueRecoveredCents += a.plan?.priceCents ?? 0;
341	    revenueApproximate = true;
342	  }
343	
344	  const emailRefs = refs("EMAIL");
345	  if (emailRefs.length) {
346	    const subs = await db.emailSubscription.findMany({
347	      where: { id: { in: emailRefs } },
348	      select: { emailPlan: { select: { priceCents: true } } },
349	    });
350	    for (const s of subs) revenueRecoveredCents += s.emailPlan?.priceCents ?? 0;
351	    revenueApproximate = true;
352	  }
353	
354	  return {
355	    total,
356	    renewed,
357	    conversion: total > 0 ? renewed / total : 0,
358	    byCampaign,
359	    revenueRecoveredCents,
360	    revenueApproximate,
361	  };
362	}
