353	/**
354	 * Place an order: validate, charge the wallet (unless a free admin grant),
355	 * create the Server + PROVISION job. Returns the new server id. Does NOT
356	 * redirect. Callers must ensure funds exist (or pass free) — this still
357	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
358	 *
359	 * `sold` overrides the recomputed price with the one the order was actually SOLD
360	 * at — the card-paid path passes the figure stamped on the Checkout session
361	 * BEFORE the card was charged, so the confirm redirect settles the price the
362	 * customer consented to instead of re-pricing against whatever promo is running
363	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
364	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
365	 * quote, which it computed moments ago in the same request. See OrderPrice.
366	 */
367	/**
368	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
369	 * any failure so nothing partial survives. Kept separate from the order tx so a
370	 * wallet order can surface the failure before any money moves, and a card order
371	 * (already paid) can swallow it without stranding the paid provision.
372	 *
373	 * Guards, all enforced here: first-time-only (no prior paid server), the
374	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
375	 * (the two @@unique constraints on CouponRedemption).
376	 */
377	async function claimOrderCoupon(opts: {
378	  couponId: string;
379	  maxRedemptions: number | null;
380	  firstTimeOnly: boolean;
381	  userId: string;
382	  ipHash: string | null;
383	  amountCents: number;
384	}): Promise<void> {
385	  await db.$transaction(async (tx) => {
386	    if (opts.firstTimeOnly) {
387	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
388	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
389	    }
390	    // Atomic conditional increment — the only thing between the last free slot and
391	    // an over-redemption when two orders race for it.
392	    const claim = await tx.coupon.updateMany({
393	      where:
394	        opts.maxRedemptions === null
395	          ? { id: opts.couponId, active: true }
396	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
397	      data: { timesRedeemed: { increment: 1 } },
398	    });
399	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
400	    try {
401	      await tx.couponRedemption.create({
402	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
403	      });
404	    } catch {
405	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
406	      // this person. Throwing rolls back the increment above with it.
407	      throw new OrderError("You’ve already used this code.");
408	    }
409	  });
410	}
