412	/**
413	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
414	 *
415	 * The card leg discounts `cardCents` up front and only settles the redemption
416	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
417	 * paid provision is never stranded. Without this pre-check, a customer who has
418	 * already used a one-per-person code (or isn't first-time) still gets the
419	 * discounted card charge and the swallow hides it. So before we send them to
420	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
421	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
422	 * (a race could still lose the atomic claim at settle time — that path stays
423	 * swallowed by design), but it closes the everyday bypass.
424	 */
425	export async function orderCouponClaimable(opts: {
426	  couponId: string;
427	  firstTimeOnly: boolean;
428	  maxRedemptions: number | null;
429	  userId: string;
430	  ipHash: string | null;
431	}): Promise<{ ok: true } | { ok: false; error: string }> {
432	  if (opts.firstTimeOnly) {
433	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
434	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
435	  }
436	  const byUser = await db.couponRedemption.findUnique({
437	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
438	  });
439	  if (byUser) return { ok: false, error: "You’ve already used this code." };
440	  if (opts.ipHash) {
441	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
442	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
443	  }
444	  if (opts.maxRedemptions !== null) {
445	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
446	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
447	  }
448	  return { ok: true };
449	}
