451	export async function placeOrder(
452	  user: User,
453	  intent: OrderIntent,
454	  sold?: OrderPrice | null,
455	  opts?: { ipHash?: string | null; campaign?: string },
456	): Promise<string> {
457	  const quote = await orderQuote(intent);
458	  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents } = quote;
459	  // Everything below bills off THESE three, never off `quote.chargeCents` /
460	  // `promo` directly: when a sold price is present it is the whole truth about
461	  // what this order costs and what rate it was sold at.
462	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
463	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
464	  const promoName = sold?.promoName || promo.name;
465	  // Note the intro discount on the billing document (first term only; renews full).
466	  const promoNote = promoPercent > 0 ? ` · ${promoName} ${promoPercent}% off first term` : "";
467	
468	  // Managed first-month-free: is the price we're settling one that carries the
469	  // credit? Wallet path prices off the fresh quote (promoCreditCents), card path
470	  // off the sold rate. Only then do we contend for the atomic claim below.
471	  const promoApplied = sold ? sold.promoPercent > 0 : promoCreditCents > 0;
472	
473	  const cap = await capacityCheck(plan.id);
474	  if (!cap.ok) throw new OrderError(cap.reason);
475	
476	  let nodeId: string | null = null;
477	  if (intent.nodeId) {
478	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
479	    if (!n) throw new OrderError("Selected location is not available.");
480	    nodeId = n.id;
481	  } else {
482	    const n = await scheduleNode(plan.ramMB);
483	    nodeId = n?.id ?? null;
484	  }
485	
486	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
487	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
488	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
489	
490	  const addons = {
491	    malwareScanner: !!intent.addonMalware,
492	    dailyBackup: !!intent.addonBackup,
493	    docker: !!intent.addonDocker,
494	  };
495	  const isAdmin = user.role === "ADMIN";
496	  const freeRequested = !!intent.free && isAdmin;
497	  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");
498	
499	  // Claim the coupon BEFORE the order tx, so a wallet order fails cleanly (no
500	  // money moved) if the last slot just went. A free admin grant never consumes a
501	  // customer coupon. On the card-settle path the payment already cleared, so a
502	  // late claim failure must not strand the paid provision — log and continue.
503	  if (!freeRequested && quote.couponId && quote.couponDiscountCents > 0) {
504	    try {
505	      await claimOrderCoupon({
506	        couponId: quote.couponId,
507	        maxRedemptions: quote.couponMaxRedemptions,
508	        firstTimeOnly: quote.couponFirstTimeOnly,
509	        userId: user.id,
510	        ipHash: opts?.ipHash ?? null,
511	        amountCents: quote.couponDiscountCents,
512	      });
513	    } catch (e) {
514	      if (!sold) throw e; // wallet path: nothing charged yet — surface it
515	      console.error(`[order] coupon claim failed on a paid order for ${user.id}`, e);
516	    }
517	  }
518	
519	  const newKey = (intent.sshPublicKey ?? "").trim();
520	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
521	
522	  let server;
523	  try {
524	    server = await db.$transaction(async (tx) => {
525	      // ATOMIC first-month-free claim, INSIDE the charge tx (mirrors claimOrderCoupon).
526	      // Contend for the redemption BEFORE debiting so the debit amount matches the
527	      // outcome. A lost claim never throws — on the wallet path we add the credit
528	      // back and charge FULL; on the card path the money already settled at the sold
529	      // price (screened by the pre-checkout guard in actions.ts), so we keep it and
530	      // record nothing — the same swallow discipline the coupon path uses.
531	      let debitCents = chargeCents;
532	      let promoNoteFinal = promoNote;
533	      let promoClaimId: string | null = null;
534	      let soldFull = false; // wallet order that lost the claim and paid full price
535	      if (!freeRequested && promoApplied) {
536	        const claim = await claimFirstMonthFree(tx, {
537	          userId: user.id,
538	          ipHash: opts?.ipHash ?? null,
539	          serviceType: "VPS",
540	          campaign: opts?.campaign ?? "",
541	          chargedCents: chargeCents,
542	        });
543	        if (claim.claimed) {
544	          promoClaimId = claim.id;
545	        } else if (!sold) {
546	          debitCents = chargeCents + promoCreditCents; // full price
547	          promoNoteFinal = "";
548	          soldFull = true;
549	        }
550	      }
551	      // The rate this term was actually sold at: 0% off when a wallet order lost the
552	      // claim and paid full, otherwise the promo/sold percent (100 admin grant).
553	      const effectivePromoPercent = freeRequested ? 100 : soldFull ? 0 : promoPercent;
554	      if (!freeRequested) {
555	        await debitWallet(tx, user.id, debitCents);
556	        await tx.walletTransaction.create({
557	          data: {
558	            userId: user.id,
559	            amountCents: -debitCents,
560	            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNoteFinal}`,
561	          },
562	        });
563	        // Billing document for the charge — created inside the same debit tx so it
564	        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
565	        // Extra disk gets its OWN line so the customer can see exactly what the
566	        // permanent storage costs; the lines always sum back to debitCents.
567	        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${term.label}${promoNoteFinal}`;
568	        // Both add-ons get their OWN line; the base plan line is the remainder, so
569	        // the lines always sum back to debitCents.
570	        const planLineCents = debitCents - extraDiskCents - backupCents;
571	        await tx.invoice.create({
572	          data: invoiceCreateData({
573	            userId: user.id,
574	            description: lineDesc,
575	            status: "PAID",
576	            period: { start: new Date(), end: addMonths(new Date(), term.months) },
577	            lineItems: [
578	              { description: lineDesc, qty: 1, unitCents: planLineCents, amountCents: planLineCents },
579	              ...(extraDiskCents > 0
580	                ? [
581	                    {
582	                      description:
583	                        `${extraDiskLabel(extraDiskGB)} — ${term.label} ` +
584	                        `($${(extraDiskMonthlyCents / 100).toFixed(2)}/mo, permanent: storage can be added but never removed)`,
585	                      qty: 1,
586	                      unitCents: extraDiskCents,
587	                      amountCents: extraDiskCents,
588	                    },
589	                  ]
590	                : []),
591	              ...(backupCents > 0
592	                ? [
593	                    {
594	                      description:
595	                        `${backupTierSpec(backupTier).label} backups (keep ${backupTierSpec(backupTier).keep}) — ${term.label} ` +
596	                        `($${(backupMonthlyCents / 100).toFixed(2)}/mo)`,
597	                      qty: 1,
598	                      unitCents: backupCents,
599	                      amountCents: backupCents,
600	                    },
601	                  ]
602	                : []),
603	            ],
604	          }),
605	        });
606	      }
607	      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
608	        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
609	        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
610	      }
611	      const s = await tx.server.create({
612	        data: {
613	          name: intent.hostname,
614	          hostname: intent.hostname,
615	          userId: user.id,
616	          planId: plan.id,
617	          osTemplateId: os.id,
618	          nodeId,
619	          addons,
620	          // The wizard sells "Daily auto-backups" ("Nightly snapshots to separate
621	          // storage for easy restore") and re-confirms it on the Review step, but
622	          // `addons.dailyBackup` was write-only: the worker declares the key and
623	          // never reads it, and the REAL scheduler (worker/backup-schedule.ts)
624	          // keys off `autoBackup` + `backupIntervalHours`, whose only writer was
625	          // the Backups tab. Nothing bridged the two, so EVERY server in the live
626	          // DB carried `addons.dailyBackup` with `autoBackup: false` and no backup
627	          // job was ever enqueued. A customer would discover the safety net they
628	          // were promised did not exist at the moment they needed it. Bridge it
629	          // here, at the point of sale. A PAID backup tier (PLUS) implies backups
630	          // are on regardless of the free "Daily auto-backups" toggle — you cannot
631	          // sell retention on a schedule that never runs. `backupTier`/`backupKeep`
632	          // are the columns the retention lever (worker/index.ts backupCreate)
633	          // reads; keep null on FREE so it falls back to the tier default.
634	          autoBackup: !!intent.addonBackup || backupTier !== "FREE",
635	          backupIntervalHours:
636	            !!intent.addonBackup || backupTier !== "FREE" ? backupTierSpec(backupTier).intervalHours : null,
637	          backupTier,
638	          backupKeep: backupTier === "FREE" ? null : backupTierSpec(backupTier).keep,
639	          termMonths: term.months,
640	          // THE RATE THIS TERM WAS SOLD AT, recorded at the moment of sale. Every
641	          // later proration prices the plan delta against this number instead of
642	          // whatever promo happens to be running when the customer clicks resize
643	          // (lib/proration.ts) — otherwise the customer chooses the rate for each
644	          // half of a round trip by choosing the date, and pockets the spread.
645	          // `chargeCents` above is literally promoPriceCents(regular, promo), so
646	          // this scalar and the cash collected describe the same transaction.
647	          // A free admin grant recorded as 100: nothing was paid for these months,
648	          // so nothing may ever prorate out of them.
649	          //
650	          // `effectivePromoPercent` — not `promo.discountPercent` — because a
651	          // card-paid order settles the rate it was SOLD at (see OrderPrice), which
652	          // may no longer be the promo running now, AND because a wallet order that
653	          // lost the first-month-free claim paid FULL price (0% off): recording 100
654	          // there would let a later downgrade prorate out a discount nobody was
655	          // charged. Recording today's rate against a price collected under a
656	          // different one is exactly the drift this column exists to prevent.
657	          termPromoPercent: effectivePromoPercent,
