21	/** Stripe's hard limit on a single metadata VALUE. */
22	export const STRIPE_METADATA_VALUE_MAX = 500;
23	
24	/**
25	 * Serialise a payload for Stripe metadata, refusing rather than truncating.
26	 *
27	 * WHY THIS EXISTS. Every one of these payloads used to be written as
28	 * `JSON.stringify(x).slice(0, 490)`. A slice through JSON produces a string that
29	 * is no longer JSON, and the consumer's `JSON.parse` throws inside a `try` that
30	 * returns `null` on failure — at which point `fulfilCheckoutSession` cannot see an
31	 * order, a resize or a disk expansion in the session, and falls through to its
32	 * plain wallet-top-up branch. The customer's card is charged, the money lands in
33	 * their wallet, **no server is created, no error is shown and no failure row is
34	 * written**. Silent, and invisible from every surface we own.
35	 *
36	 * The correct behaviour was already argued for elsewhere in this file, about the
37	 * card leg: "Refuse to open a session rather than take the money and discover it
38	 * at confirm time — nothing has been charged at this point." That reasoning
39	 * applies identically here, so it is applied identically. Throwing happens BEFORE
40	 * `checkout.sessions.create`, so the customer sees a failure on a page where they
41	 * have paid nothing, which is the cheapest possible moment to fail.
42	 *
43	 * Never re-introduce a slice here. If a payload legitimately outgrows the cap, the
44	 * fix is to persist it and put a key in metadata — never to send half of it.
45	 */
46	export function packMetadata(label: string, payload: unknown): string {
47	  const json = JSON.stringify(payload);
48	  if (json.length > STRIPE_METADATA_VALUE_MAX) {
49	    throw new Error(
50	      `${label} is ${json.length} characters, over Stripe's ${STRIPE_METADATA_VALUE_MAX}-character metadata limit. ` +
51	        `Refusing to create a payment session rather than send a truncated payload that would take the money and ` +
52	        `provision nothing.`,
53	    );
54	  }
55	  return json;
56	}
