58	/**
59	 * Create a Checkout session that pays for a VPS order directly (no wallet pre-fund).
60	 *
61	 * `amountCents` is the CARD leg only (the remainder after wallet credit); the FULL
62	 * order total rides along in metadata as `nxeonOrderPrice` so the confirm route can
63	 * settle the price this order was SOLD at instead of re-pricing it once the card
64	 * has already cleared. That re-pricing — and the silent wallet draw that paid for
65	 * it — is the H2 incident described on `OrderPrice` in lib/order.ts.
66	 *
67	 * `sold` lets the caller hand in the very quote it split the payment from, so the
68	 * card leg and the stamped total are two halves of ONE pricing. When it is omitted
69	 * the order is priced here, once, at the moment the session is created — still
70	 * before any money moves, which is the property that matters.
71	 */
72	export async function createOrderCheckout(
73	  user: { id: string; email: string },
74	  amountCents: number,
75	  intent: OrderIntent,
76	  sold?: OrderPrice | null,
77	  campaign?: string,
78	): Promise<string | null> {
79	  if (!stripeConfigured() || amountCents <= 0) return null;
80	  const base = process.env.APP_URL ?? "http://localhost:3000";
81	  const price = sold ?? orderPriceOf(await orderQuote(intent));
82	  // The card leg is a PART of the total; a card charge larger than the whole order
83	  // means the two were priced against different worlds and the wallet would have to
84	  // absorb a negative. Refuse to open a session rather than take the money and
85	  // discover it at confirm time — nothing has been charged at this point.
86	  if (price.chargeCents < amountCents) {
87	    throw new Error(
88	      `Order checkout: card leg ${amountCents}c exceeds the order total ${price.chargeCents}c`,
89	    );
90	  }
91	  // SSH keys are long; keep them out of Stripe metadata (500-char cap) — addable after deploy.
92	  const slim: OrderIntent = { ...intent, sshPublicKey: undefined, sshKeyName: undefined };
93	  const session = await stripe().checkout.sessions.create({
94	    mode: "payment",
95	    customer_email: user.email,
96	    line_items: [
97	      {
98	        price_data: {
99	          currency: "usd",
100	          product_data: { name: `Nxeon VPS — ${intent.hostname}` },
101	          unit_amount: amountCents,
102	        },
103	        quantity: 1,
104	      },
105	    ],
106	    metadata: {
107	      nxeonUserId: user.id,
108	      nxeonOrder: packMetadata("Order intent", slim),
109	      // Its OWN key, not a field inside `nxeonOrder`, so the two are independently
110	      // sized and a long intent can never displace the price.
111	      nxeonOrderPrice: packMetadata("Order price", price),
112	      // First-month-free ad campaign tag (from the /go link cookie), carried through
113	      // the card round-trip so the redemption records attribution at fulfil time —
114	      // the webhook has no request cookies to read it from.
115	      nxeonPromoCampaign: sanitizeCampaign(campaign),
116	    },
117	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
118	    cancel_url: `${base}/dashboard/deploy?canceled=1`,
119	  });
120	  return session.url;
121	}
