223	  if (typeof raw !== "number" || !Number.isInteger(raw) || raw < 0) return null;
224	  return raw;
225	}
226	
227	function parseId(raw: unknown): string | null {
228	  return typeof raw === "string" && raw.length > 0 ? raw : null;
