231	/**
232	 * WHAT a paid Checkout session was for — the ONE decision that routes fulfilment.
233	 *
234	 * REAL DEFECT this shape exists to remove (found 2026-07-27 audit). Fulfilment used
235	 * to ask three separate `getCheckout*Intent` helpers, each of which did its OWN
236	 * `sessions.retrieve` inside a `try` that returned `null` on ANY failure. So a
237	 * transient Stripe error — a 5xx, a rate limit, a dropped socket — turned "I could
238	 * not read this session" into "this session has no purchase metadata", and
239	 * `fulfilCheckoutSession` fell through to its plain wallet-top-up branch reporting
240	 * `fulfilled: true`. Card charged, no server, no `FulfilledSession` row, no
241	 * notification, and the webhook returns 200 so Stripe never retries. Exactly the
242	 * class of invisible failure that file was written to end, one layer up.
243	 *
244	 * `unreadable` and `unpaid` are therefore first-class answers, NOT absences. The
245	 * session is retrieved exactly once (`getCheckoutPurpose`, which THROWS rather than
246	 * returning a lie) and classified by a pure function over its metadata.
247	 */
248	export type CheckoutPurpose =
249	  | { kind: "order"; userId: string; intent: OrderIntent; sold: OrderPrice | null; campaign: string }
250	  | { kind: "resize"; userId: string; serverId: string; planId: string; chargeCents: number }
251	  | { kind: "diskExpand"; userId: string; serverId: string; addGB: number; chargeCents: number }
252	  /** No purchase metadata: a wallet top-up the customer bought for its own sake. */
253	  | { kind: "topup"; userId: string | null }
254	  /** Not paid (or paid to nobody) — nothing to fulfil and nothing to claim. */
255	  | { kind: "unpaid" }
256	  /** Purchase metadata IS present but cannot be trusted. Never treat as a top-up. */
257	  | { kind: "unreadable"; userId: string | null; detail: string };
258	
259	/**
260	 * Classify a retrieved session. Pure — no clock, no network, no database — so the
261	 * routing decision is unit-testable and identical for the redirect and the webhook.
262	 */
263	export function classifyCheckoutSession(
264	  session: Pick<Stripe.Checkout.Session, "metadata" | "payment_status">,
265	): CheckoutPurpose {
266	  const md = session.metadata ?? null;
267	  const userId = parseId(md?.nxeonUserId);
268	  if (!userId || session.payment_status !== "paid") return { kind: "unpaid" };
269	
270	  const orderRaw = md?.nxeonOrder;
271	  if (orderRaw) {
272	    let intent: unknown;
273	    try {
274	      intent = JSON.parse(orderRaw);
275	    } catch {
276	      return { kind: "unreadable", userId, detail: "nxeonOrder is not valid JSON" };
277	    }
278	    if (!intent || typeof intent !== "object") {
279	      return { kind: "unreadable", userId, detail: "nxeonOrder is not an object" };
280	    }
281	    return {
282	      kind: "order",
283	      userId,
284	      intent: intent as OrderIntent,
285	      sold: parseOrderPrice(session.metadata?.nxeonOrderPrice),
286	      campaign: sanitizeCampaign(md?.nxeonPromoCampaign),
287	    };
288	  }
289	
290	  const resizeRaw = md?.nxeonResize;
291	  if (resizeRaw) {
292	    let p: Record<string, unknown>;
293	    try {
294	      p = JSON.parse(resizeRaw) as Record<string, unknown>;
295	    } catch {
296	      return { kind: "unreadable", userId, detail: "nxeonResize is not valid JSON" };
297	    }
298	    const serverId = parseId(p?.serverId);
299	    const planId = parseId(p?.planId);
300	    const chargeCents = parseChargeCents(p?.chargeCents);
301	    if (!serverId || !planId || chargeCents === null) {
302	      return { kind: "unreadable", userId, detail: "nxeonResize is missing serverId/planId/chargeCents" };
303	    }
304	    return { kind: "resize", userId, serverId, planId, chargeCents };
305	  }
306	
307	  const expandRaw = md?.nxeonDiskExpand;
308	  if (expandRaw) {
309	    let p: Record<string, unknown>;
310	    try {
311	      p = JSON.parse(expandRaw) as Record<string, unknown>;
312	    } catch {
313	      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is not valid JSON" };
314	    }
315	    const serverId = parseId(p?.serverId);
316	    const addGB = parseChargeCents(p?.addGB);
317	    const chargeCents = parseChargeCents(p?.chargeCents);
318	    if (!serverId || addGB === null || chargeCents === null) {
319	      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is missing serverId/addGB/chargeCents" };
320	    }
321	    return { kind: "diskExpand", userId, serverId, addGB, chargeCents };
322	  }
323	
324	  return { kind: "topup", userId };
325	}
