341	/**
342	 * True when this session's card payment is the FUNDING LEG of a purchase — a VPS
343	 * order, an upgrade, a disk expansion — rather than a wallet top-up the customer
344	 * bought for its own sake.
345	 *
346	 * The wallet is the settlement bus for every card-paid purchase: the card amount
347	 * is credited in, then the purchase debits the full total back out. That credit is
348	 * plumbing, not a product, and it must not be documented as one.
349	 *
350	 * REAL INCIDENT (2026-07-26 rehearsal, H3): every paid session got a PAID "Wallet
351	 * top-up" invoice here AND a PAID invoice from whatever it funded, so one $82.53
352	 * annual purchase produced `Wallet top-up $82.53` + `Starter VPS — Annual $82.53`
353	 * and the invoices page reported $165.06 paid lifetime — a customer reconciling
354	 * against their card statement saw twice their spend. Each document was internally
355	 * consistent; there were simply two of them for one payment. worker/billing.ts
356	 * already states the rule for the renewal path: "No invoice for the card leg …
357	 * a second document for the card portion would double-count the same revenue."
358	 *
359	 * Reads the same three metadata keys `lib/fulfil-checkout.ts` dispatches on, so
360	 * "did this session fund a purchase" has one answer, not two.
361	 */
362	export function isPurchaseLegSession(metadata: Stripe.Metadata | null | undefined): boolean {
363	  return !!(metadata?.nxeonOrder || metadata?.nxeonResize || metadata?.nxeonDiskExpand);
364	}
