366	/**
367	 * Credit a user's wallet for a completed Checkout session, idempotently.
368	 * Called from both the success-redirect confirm route (works without HTTPS)
369	 * and the webhook (belt-and-suspenders once HTTPS is available).
370	 * Returns true if a credit was applied this call.
371	 *
372	 * Takes the ALREADY-RETRIEVED session rather than an id: `fulfilCheckoutSession`
373	 * fetches it once and both the credit and the fulfilment routing read that single
374	 * object, so the two can never disagree about what this payment was (and a Stripe
375	 * read failure surfaces in one place, loudly, instead of four times as `null`).
376	 */
377	export async function creditCheckoutSession(session: Stripe.Checkout.Session): Promise<boolean> {
378	  const userId = session.metadata?.nxeonUserId;
379	  const cents = session.amount_total ?? 0;
380	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
381	
382	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
383	  // session id inside the description.
384	  const legacy = await db.walletTransaction.findFirst({
385	    where: { stripeSessionId: null, description: { contains: session.id } },
386	  });
387	  if (legacy) return false;
388	
389	  // Is this credit a product the customer bought, or the funding leg of something
390	  // else they bought? Only the first is a "Wallet top-up" and only the first gets
391	  // a billing document — see isPurchaseLegSession for the incident.
392	  const purchaseLeg = isPurchaseLegSession(session.metadata);
393	
394	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
395	  // read-then-write check. The confirm-redirect and the webhook can arrive
396	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
397	  // only the database can safely decide the winner. P2002 == already credited.
398	  const ops: Prisma.PrismaPromise<unknown>[] = [
399	    db.walletTransaction.create({
400	      data: {
401	        userId,
402	        amountCents: cents,
403	        description: `Stripe payment (${session.id})`,
404	        stripeSessionId: session.id,
405	      },
406	    }),
407	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
408	    db.notification.create({
409	      data: {
410	        userId,
411	        title: `Payment of $${(cents / 100).toFixed(2)} received`,
412	        href: "/dashboard/billing",
413	      },
414	    }),
415	  ];
416	  // Index of the invoice-create inside `ops`, or -1 when no invoice is issued
417	  // (a purchase leg). Used to recover the new invoice's id for the receipt email.
418	  let invoiceOpIndex = -1;
419	  if (!purchaseLeg) {
420	    // PAID invoice for the top-up. Created in the SAME guarded transaction as
421	    // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
422	    // the credit idempotent also prevents a duplicate invoice on replay.
423	    //
424	    // A purchase leg is deliberately left undocumented HERE: the order, resize or
425	    // disk-expansion it funds issues the one invoice for the whole purchase, and
426	    // that document — not this one — is what the customer's card statement shows.
427	    // If the fulfilment then fails the money stays in the wallet as an ordinary
428	    // credit (ledger row + notification), and the invoice is issued by whatever it
429	    // is eventually spent on; inventing a top-up document at that point would
430	    // double-count the same dollars all over again the moment they deploy.
431	    // Remember WHERE in the batch this lands, so the created row's id can be read
432	    // back out of the transaction result. The receipt email promises the customer
433	    // an attached invoice, and it can only keep that promise if it knows the id.
434	    invoiceOpIndex = ops.length;
435	    ops.push(
436	      db.invoice.create({
437	        data: invoiceCreateData({
438	          userId,
439	          description: "Wallet top-up",
440	          status: "PAID",
441	          lineItems: [
442	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
443	          ],
444	        }),
445	      }),
446	    );
447	  }
448	  let invoiceId: string | undefined;
449	  try {
450	    const results = await db.$transaction(ops);
451	    if (invoiceOpIndex >= 0) {
452	      const created = results[invoiceOpIndex] as { id?: string } | undefined;
453	      invoiceId = created?.id;
454	    }
455	  } catch (e) {
456	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
457	    throw e;
458	  }
459	  // A funded wallet is the referred user's first paid action — reward both sides.
460	  try {
461	    const { maybeRewardReferral } = await import("./actions-growth");
462	    await maybeRewardReferral(userId);
463	  } catch { /* best-effort */ }
464	  try {
465	    const u = await db.user.findUnique({ where: { id: userId } });
466	    if (u) {
467	      const { sendMail, emails } = await import("./mailer");
468	      // Say what the money was for. On a purchase leg it is emphatically NOT a
469	      // top-up, and a receipt that calls it one is the same false statement the
470	      // duplicate invoice used to make, just in the customer's inbox.
471	      // The third argument is the promise, and it is the truth: we claim an attached
472	      // invoice only when there is an invoice id to attach. A purchase leg issues no
473	      // top-up invoice (the order does), so its receipt points at billing history
474	      // instead of promising a file that was never generated.
475	      const tpl = emails.receipt(
476	        `$${(cents / 100).toFixed(2)}`,
477	        purchaseLeg ? "your Nxeon order" : "wallet top-up",
478	        !!invoiceId,
479	      );
480	      // `kind` + `userId` hands this to the preference policy in lib/prefs.ts.
