424	export async function payAndDeploy(
425	  prev: any,
426	  formData: FormData,
427	): Promise<{ error?: string; checkoutUrl?: string }> {
428	  const user = await requireUser();
429	  // Spend path: never move a customer's money while an admin is impersonating them.
430	  await assertNotImpersonating();
431	  // Same verification gate every purchase path applies. This is the CARD path, so it is the
432	  // one where an unreachable address is most expensive: without it we would take
433	  // a real payment for a machine whose credentials have nowhere to go.
434	  const unverified = await emailVerificationError(user);
435	  if (unverified) return { error: unverified };
436	  // Per-user server cap — the same one `orderGameServer` enforces for game tiers.
437	  const limitErr = await serverLimitError(user.id);
438	  if (limitErr) return { error: limitErr };
439	  const intent = intentFromFormData(formData);
440	
441	  let quote;
442	  try {
443	    quote = await orderQuote(intent);
444	  } catch (e) {
445	    if (e instanceof OrderError) return { error: e.message };
446	    throw e;
447	  }
448	
449	  // Managed first-month-free eligibility. If this account/IP has ALREADY redeemed
450	  // the promo (or it's switched off), re-quote at FULL price so the wallet split,
451	  // the card leg and the stamped total are all full — the free month is a
452	  // once-per-person offer. The wallet path is self-correcting regardless (its
453	  // atomic claim inside placeOrder charges full on a lost claim), but the CARD
454	  // leg settles up front, so it MUST be priced full here or a repeat customer
455	  // gets a second discounted checkout. This mirrors the coupon guard below.
456	  // `|| null` matters: hashIp returns "" when the IP is unavailable, and an empty
457	  // string is a REAL value to the (promoId, ipHash) unique — it would collide
458	  // across every IP-less redemption and wrongly block them. NULLs are distinct.
459	  const promoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
460	  if (quote.promoCreditCents > 0 && !(await firstMonthFreeEligible(user.id, promoIpHash))) {
461	    quote = await orderQuote(intent, { suppressPromo: true });
462	  }
463	  const promoCampaign = promoCampaignFromCookie(await cookies());
464	
465	  const isAdmin = user.role === "ADMIN";
466	  const freePath = !!intent.free && isAdmin;
467	
468	  // Wallet-aware split. The customer's Review screen computes the exact same split
469	  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
470	  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
471	  // the balance. Free admin grants skip the split entirely (no money moves).
472	  const useWallet = formData.get("useWallet") !== "0";
473	  const { walletApplied, cardCents } = freePath
474	    ? { walletApplied: 0, cardCents: 0 }
475	    : walletSplit({ dueCents: quote.chargeCents, balanceCents: user.balanceCents, useWallet });
476	
477	  // Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
478	  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
479	  // (or nothing, for a free grant); the balance check inside it holds because a
480	  // $0 card portion means balance >= chargeCents.
481	  if (freePath || cardCents <= 0) {
482	    let serverId: string;
483	    try {
484	      // Reuse the request-scoped IP hash computed above so placeOrder can enforce
485	      // both the coupon's once-per-person guard and the first-month-free 1/IP cap.
486	      serverId = await placeOrder(user, intent, null, { ipHash: promoIpHash, campaign: promoCampaign });
487	    } catch (e) {
488	      if (e instanceof OrderError) return { error: e.message };
489	      throw e;
490	    }
491	    redirect(`/dashboard/servers/${serverId}`);
492	  }
493	
494	  // Coupon guard for the CARD path. The wallet path is already safe — its
495	  // placeOrder claim throws and we surface it above (nothing charged). But the
496	  // card leg below discounts `cardCents` up front and settles the redemption only
497	  // AFTER the card clears, where a failed claim is swallowed so a paid provision
498	  // isn't stranded. So a customer who already used a one-per-person code would
499	  // still get the discounted charge. Re-run the per-person guards as reads here
500	  // and refuse before checkout — same messages the wallet path would show.
501	  if (quote.couponId) {
502	    const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon");
503	    const claimable = await orderCouponClaimable({
504	      couponId: quote.couponId,
505	      firstTimeOnly: quote.couponFirstTimeOnly,
506	      maxRedemptions: quote.couponMaxRedemptions,
507	      userId: user.id,
508	      ipHash,
509	    });
510	    if (!claimable.ok) return { error: `${claimable.error} Remove the code to continue at the regular price.` };
511	  }
512	
513	  // Card portion > 0 → charge ONLY the remainder on the card (not the full total).
514	  // On payment success the confirm route credits this card amount to the wallet and
515	  // then placeOrder debits the full chargeCents, so the wallet naturally absorbs
516	  // `walletApplied` and the card the rest — the wallet is never touched before the
517	  // card clears. (walletApplied is implied by cardCents vs. the recomputed charge,
518	  // so it needs no separate metadata field.)
519	  // The price is handed over EXPLICITLY, from the very quote the wallet split above
520	  // was computed from. Without this argument `createOrderCheckout` re-quotes
521	  // internally, microseconds later, from its own `new Date()` — the same function,
522	  // so no formula can drift, but two different instants. A promo boundary (or an
523	  // operator changing a plan price) falling between them would mean the card leg
524	  // and the stamped total were priced against two different worlds, and the wallet
525	  // would silently absorb the difference. One quote, one price, one charge.
526	  const url = await createOrderCheckout(user, cardCents, intent, orderPriceOf(quote), promoCampaign);
527	  if (!url) return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
528	  return { checkoutUrl: url };
529	}
