export type ReserveResult = { reserved: true; token: string } | { reserved: false };

/**
 * THE CARD/STRIPE HOLD. Insert a RESERVED redemption BEFORE the card is charged, so
 * a second concurrent checkout can't also pass eligibility and walk away with a
