 * any Stripe session exists. The returned `token` is stamped into the Checkout
 * session's metadata and is what `confirmReservation` / `releaseReservation` target.
 */
export async function reserveFirstMonthFree(opts: {
  userId: string;
  ipHash: string | null;
  serviceType: PromoServiceType;
  campaign: string;
  chargedCents: number;
  /** When this hold may be reaped if never confirmed (session lifetime + grace). */
  reservedUntil: Date;
}): Promise<ReserveResult> {
  const d = promoDelegate(db);
  const token = `pmr_${randomUUID()}`;
