    // Clear this claimant's own dead holds first, so an earlier abandoned checkout
    // never blocks a new one — the "no permanently-burned eligibility" guarantee.
    await releaseExpiredReservationsFor(d, opts.userId, opts.ipHash);
    await d.create({
      data: {
        promoId: FIRST_MONTH_FREE_PROMO_ID,
        userId: opts.userId,
        ipHash: opts.ipHash,
        serviceType: opts.serviceType,
        campaign: opts.campaign,
        chargedCents: opts.chargedCents,
