/**
 * Confirm a hold at fulfilment: flip its RESERVED row to CONSUMED, inside the order's
 * charge tx so the grant commits with the money. The `state: RESERVED` guard makes it
 * idempotent (a replayed fulfil, or a race with the sweep, matches zero rows) and
 * guarantees we never "confirm" a hold that was already released. Returns the row id
 * (to anchor `orderRef`), or null when there is no live hold to confirm.
 */
export async function confirmReservation(
  tx: Prisma.TransactionClient,
  token: string,
): Promise<{ id: string } | null> {
  const d = promoDelegate(tx);
  const row = await d.findFirst({
    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, reservationToken: token },
    select: { id: true },
  });
  if (!row) return null;
  const res = await d.updateMany({
    where: { promoId: FIRST_MONTH_FREE_PROMO_ID, reservationToken: token, state: PROMO_STATE.RESERVED },
    data: { state: PROMO_STATE.CONSUMED, reservedUntil: null },
  });
  // count 0 => it was already consumed (a replay) or released; either way there is
  // nothing to newly grant on this call.
  return res.count === 1 ? { id: row.id } : null;
}

