import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { classifyCheckoutSession } from "../lib/stripe.ts";

/**
 * THE MONEY RACE (documented, low-severity, real): the first-month-free credit is
 * granted at most once per account AND once per IP (two @@unique constraints on
 * PromoRedemption). Every order flow is atomic EXCEPT the up-front-settlement
 * (card/Stripe) path, which pre-screened eligibility, opened a discounted Checkout,
 * and only claimed the redemption at FULFILMENT — so two card checkouts submitted
 * concurrently, both before either redemption row landed, could each pass
 * eligibility and each collect a free month from ONE eligibility.
 *
 * THE FIX: RESERVE the redemption at checkout-CREATE time (before Stripe), keyed to
 * the session by a token in metadata; CONFIRM it at fulfilment; RELEASE it on
 * expiry/sweep. A second concurrent create can't also reserve (the reserve's INSERT
 * contends on the same two unique constraints), so it re-quotes at FULL price.
 *
 * These are DB-free proofs — the pure classifier plus source tripwires — of the
 * shape of the fix. They are NOT an end-to-end test of the concurrent claim, which
 * needs a live database.
 */

function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

function session(metadata: Record<string, string> | null, paid = true) {
  return { metadata, payment_status: (paid ? "paid" : "unpaid") as "paid" | "unpaid" };
}

/* ------------------------------------------------------------------ *
 * The hold token round-trips through the Checkout session
 * ------------------------------------------------------------------ */

test("a card order carries its first-month-free hold token so fulfilment can CONFIRM it", () => {
  const p = classifyCheckoutSession(
    session({
      nxeonUserId: "u1",
      nxeonOrder: '{"planId":"p1","osTemplateId":"os1","hostname":"web"}',
      nxeonPromoReservation: "pmr_abc-123",
    }),
  );
  assert.equal(p.kind, "order");
  assert.equal(p.kind === "order" && p.promoReservationToken, "pmr_abc-123");
});

test("a full-price card order carries NO hold token (nothing to confirm, nothing to grant)", () => {
  const p = classifyCheckoutSession(
    session({ nxeonUserId: "u1", nxeonOrder: '{"planId":"p1","osTemplateId":"os1","hostname":"web"}' }),
  );
  assert.equal(p.kind, "order");
  // Absent metadata parses to null — never "", which parseId already rejects.
  assert.equal(p.kind === "order" && p.promoReservationToken, null);
});

/* ------------------------------------------------------------------ *
 * The reservation is taken BEFORE the card is charged
 * ------------------------------------------------------------------ */

test("payAndDeploy RESERVES the credit before opening the Checkout session", () => {
  const actions = code("../lib/actions.ts");
  const reserveAt = actions.indexOf("reserveFirstMonthFree(");
  const checkoutAt = actions.indexOf("createOrderCheckout(user, cardCents");
  assert.ok(reserveAt > 0, "the card path reserves the first-month-free credit");
  assert.ok(checkoutAt > 0, "the card path opens a Checkout session");
  assert.ok(
    reserveAt < checkoutAt,
    "the reserve must precede the session — a hold taken AFTER the discounted session " +
      "exists would leave a window where a second checkout also passes eligibility",
  );
});

test("a lost reservation re-quotes the card leg at FULL price (displayed === charged)", () => {
  const actions = code("../lib/actions.ts");
  // The reserve-failure branch re-prices at full and recomputes the split, so the
  // stamped total and the card leg agree with what the customer will be charged.
  assert.match(
    actions,
    /orderQuote\(intent, \{ suppressPromo: true \}\)[\s\S]*?walletSplit\(/,
    "on a lost hold the order must be re-quoted full and the split recomputed",
  );
});

test("opening the session is passed the hold token, and a failed open RELEASES the hold", () => {
  const actions = code("../lib/actions.ts");
  assert.match(
    actions,
    /createOrderCheckout\(user, cardCents, intent, orderPriceOf\(quote\), promoCampaign, promoReservationToken\)/,
    "the hold token is stamped onto the session",
  );
  assert.match(
    actions,
    /releaseReservation\(promoReservationToken\)/,
    "a session that never comes into being must not strand the customer's one-time offer",
  );
});

/* ------------------------------------------------------------------ *
 * Fulfilment CONFIRMS the reserved hold — never a fresh contended claim
 * ------------------------------------------------------------------ */

test("the card path confirms the reserved hold instead of racing a fresh INSERT", () => {
  const order = code("../lib/order.ts");
  assert.match(order, /confirmReservation\(tx, cardPromoToken\)/, "card path confirms the hold");
  // The old, racy signal — infer 'first month free' from the stamped promo percent —
  // is gone. currentPromo() always stamps 100, even on a full-price VPS card order,
  // so that signal would record a redemption for a purchase that never got one.
  assert.ok(
    !/sold\s*\?\s*sold\.promoPercent\s*>\s*0/.test(order),
    "the card path must not gate the first-month-free claim on sold.promoPercent",
  );
});

test("fulfilment forwards the hold token from session metadata into placeOrder", () => {
  const fulfil = code("../lib/fulfil-checkout.ts");
  assert.match(
    fulfil,
    /promoReservationToken: order\.promoReservationToken/,
    "the token read off the session must reach placeOrder so the hold is confirmed",
  );
});

/* ------------------------------------------------------------------ *
 * Release paths can NEVER revoke a granted (CONSUMED) free month
 * ------------------------------------------------------------------ */

test("release and sweep are guarded to RESERVED — a confirmed grant is never revoked", () => {
  const promo = code("../lib/promo-redemption.ts");
  // releaseReservation deletes by token AND state RESERVED.
  assert.match(
    promo,
    /reservationToken: token, state: PROMO_STATE\.RESERVED/,
    "releaseReservation must be guarded to RESERVED",
  );
  // sweepExpiredReservations deletes RESERVED + past-due only.
  assert.match(
    promo,
    /state: PROMO_STATE\.RESERVED, reservedUntil: \{ lt: now \}/,
    "the sweep must only reap RESERVED holds whose window has lapsed",
  );
});

test("the expired-checkout webhook releases the hold (offer returned on abandonment)", () => {
  const hook = code("../app/api/stripe/webhook/route.ts");
  assert.match(hook, /checkout\.session\.expired/, "the webhook handles the expiry event");
  assert.match(hook, /releaseReservation\(token\)/, "and releases the hold the session carried");
});

test("the worker sweeps expired holds as a backstop for a missed webhook", () => {
  const worker = code("../worker/index.ts");
  assert.match(worker, /sweepExpiredReservations\(\)/, "the worker loop reaps dead holds");
});
